"""One-shot repair for index.html corruption caused by HTML re-serialization.

The write path injected stray closing tags into text/CSS/JS. We rebuild the
two corrupted blocks from scratch and delete every injected stray tag.
"""
import re
from pathlib import Path

HTML = Path(__file__).with_name("index.html")
s = HTML.read_text(encoding="utf-8")

# Sanity guard: only run when the known corruption markers are present.
markers = ["</head>(--bg)", "</style>100vh", "var(--amber)':'var(--green'}"]
assert any(m in s for m in markers), "unexpected file state, refusing to clobber"

# 1. Rebuild the <style> block (everything between "<style>" and "</style>").
new_style = """\
<style>
:root{--bg:#0d0d0d;--card:#171717;--card2:#121212;--fg:#fafafa;--muted:#a1a1a1;--faint:#666;--line:#292929;--soft:#202020;--green:#35e878;--red:#ff777d;--amber:#f0c76b;--mono:ui-monospace,SFMono-Regular,Consolas,monospace;--sans:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:var(--bg);color:var(--fg);font:12px/1.45 var(--sans)}button,input,select{font:inherit}.shell{height:100vh;display:grid;grid-template:40px 46px 1fr 23px/52px 1fr;grid-template-areas:"rail top" "rail run" "rail main" "rail status"}.rail,.top,.run,.status{background:var(--card2);border-color:var(--line)}.rail{grid-area:rail;border-right:1px solid var(--line);display:flex;flex-direction:column;align-items:center;padding:10px 0;gap:4px}.logo{width:28px;height:28px;background:var(--green);color:#06120a;display:grid;place-items:center;font:800 12px var(--mono);margin-bottom:14px}.r{width:34px;height:34px;display:grid;place-items:center;color:var(--faint);font-size:15px;border-left:2px solid transparent}.r.active{color:var(--green);background:#35e87812;border-left-color:var(--green)}.spacer{flex:1}.top{grid-area:top;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 14px;gap:0}.crumb,.run,.status,.select,table{font-family:var(--mono)}.crumb{color:var(--muted);font-size:11px}.crumb b{color:var(--fg)}.grow{flex:1}.search{width:240px;padding:5px 10px;background:var(--card);color:var(--fg);border:1px solid var(--line)}.tb{height:39px;padding:0 12px;display:flex;align-items:center;gap:6px;color:var(--muted);border-left:1px solid var(--soft);font:11px var(--mono)}.dot{width:6px;height:6px;background:var(--green);display:inline-block;box-shadow:0 0 0 3px #35e87822}.avatar{width:24px;height:24px;background:#303030;display:grid;place-items:center;font:10px var(--mono)}.run{grid-area:run;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 14px;gap:10px}.label,.head h2,.klabel{color:var(--faint);font:10px var(--mono);letter-spacing:.08em;text-transform:uppercase}.select{background:var(--card);color:var(--fg);border:1px solid var(--line);padding:6px 10px}.suite{display:flex;gap:16px;margin-left:10px;color:var(--muted);font:11px var(--mono)}.suite b{color:var(--fg)}.btn{padding:7px 12px;background:var(--card2);color:var(--fg);border:1px solid var(--line);cursor:pointer}.btn:hover{background:#282828}.primary{background:var(--green);border-color:var(--green);color:#06120a;font-weight:700}.main{grid-area:main;min-height:0;overflow:auto;display:grid;grid-template-columns:270px minmax(450px,1fr) 320px;grid-template-rows:auto 285px 1fr;grid-template-areas:"kpi kpi kpi" "left charts right" "left grid right";gap:1px;background:var(--line)}.pane,.kpi{background:var(--bg);min-height:0;overflow:hidden}.kpis{grid-area:kpi;display:grid;grid-template-columns:repeat(6,1fr);gap:1px;background:var(--line)}.kpi{background:var(--card2);padding:11px 16px}.klabel{margin-bottom:6px}.value{font:600 20px var(--mono)}.value small{font-size:11px;color:var(--muted);font-weight:400}.delta{font:10px var(--mono);color:var(--green);margin-top:4px}.head{height:39px;padding:8px 14px;display:flex;align-items:center;gap:8px;background:var(--card2);border-bottom:1px solid var(--line)}.head h2{margin:0;color:var(--muted);font-weight:700}.count{padding:1px 6px;background:#292929;color:var(--faint);font:10px var(--mono)}.body{overflow:auto;height:calc(100% - 39px)}.candidate{display:grid;grid-template-columns:8px 1fr 55px;gap:8px;padding:9px 14px;border-bottom:1px solid var(--soft);cursor:pointer}.candidate:hover,.candidate.selected{background:#35e8780d}.candidate.selected{border-left:2px solid var(--green);padding-left:12px}.state{width:6px;height:6px;border-radius:50%;margin-top:5px;background:var(--green)}.base .state{background:#aaa}.name{font:11px var(--mono)}.sub{color:var(--faint);font:9.5px var(--mono);margin-top:2px}.rate{text-align:right;font:11px var(--mono)}.badge{font:8px var(--mono);border:1px solid var(--faint);color:#aaa;padding:0 4px}.charts{grid-area:charts}.chartgrid{height:calc(100% - 39px);display:grid;grid-template-columns:1.3fr 1fr;gap:1px;background:var(--line)}.chart{background:var(--bg);padding:14px}.charttitle{color:var(--faint);font:9.5px var(--mono);text-transform:uppercase;margin-bottom:10px}.legend{color:var(--muted);font:9.5px var(--mono);margin-top:8px}.grid{grid-area:grid}.right{grid-area:right}.tabs{margin-left:auto;display:flex;gap:3px}.tab{padding:4px 8px;color:var(--faint);cursor:pointer;font:10px var(--mono);border:1px solid transparent}.tab.active{color:var(--green);border-color:var(--line);background:var(--card)}table{border-collapse:collapse;width:100%;min-width:760px}th,td{padding:7px 12px;text-align:left;border-bottom:1px solid var(--soft);white-space:nowrap}th{position:sticky;top:0;background:var(--card2);color:var(--faint);font-size:9.5px;text-transform:uppercase}td{font-size:11px}tbody tr:hover,tbody tr.active{background:#35e8780c}.pass{color:var(--green)}.fail{color:var(--red)}.running{color:var(--amber)}.summary{max-width:280px;overflow:hidden;text-overflow:ellipsis;color:var(--muted);font-family:var(--sans)}.inspect{padding:14px;border-bottom:1px solid var(--line)}.ilabel{color:var(--faint);font:9.5px var(--mono);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px}.ititle{font:13px var(--mono)}.isub{color:var(--faint);font:10.5px var(--mono)}.kv{display:grid;grid-template-columns:1fr auto;gap:6px;margin-top:10px;font:11px var(--mono)}.kv span:nth-child(odd){color:var(--faint)}.response{padding:10px;background:var(--card2);border:1px solid var(--line);white-space:pre-wrap;color:var(--muted);max-height:200px;overflow:auto}.status{grid-area:status;border-top:1px solid var(--line);display:flex;align-items:center;padding:0 14px;gap:18px;color:var(--faint);font:10px var(--mono)}@media(max-width:1050px){.main{grid-template-columns:230px minmax(400px,1fr);grid-template-areas:"kpi kpi" "left charts" "left grid" "right right"}.right{min-height:300px}.suite{display:none}}@media(max-width:700px){.shell{grid-template-columns:0 1fr}.rail{display:none}.main{display:block}.kpis{grid-template-columns:repeat(2,1fr)}.pane{min-height:300px}.search{width:130px}.tb{display:none}}
</style>"""
s = re.sub(r"<style>[\s\S]*?</style>", new_style, s, count=1)

# 2. Rebuild the corrupted <script> block line-by-line.
new_script = """\
<script>
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[], summaries={}, selected=null, active='all', eventSource=null;
function setStatus(s,running=false){$('#status').textContent=s.toUpperCase();$('.dot').style.background=running?'var(--amber)':'var(--green)'}
function renderRows(){let q=$('#filter').value.toLowerCase(),data=rows.filter(r=>(active==='all'||!r.pass)&&JSON.stringify(r).toLowerCase().includes(q));$('#rowCount').textContent=data.length;$('#results').innerHTML=data.length?data.map((r,i)=>`<tr data-i="${i}" class="${selected===r?'active':''}"><td>${esc(r.model)}</td><td>${esc(r.case)}</td><td class="${r.status==='error'?'fail':r.status==='running'?'running':'pass'}">${esc(r.status||'completed')}</td><td class="${r.pass?'pass':'fail'}">${r.pass==null?'—':r.pass?'PASS':'FAIL'}</td><td>${r.metrics?.elapsed_ms??'—'} ms<br><small>TTFT ${r.metrics?.ttft_ms??'—'} ms · ${r.metrics?.tok_per_sec??'—'} tok/s</small></td><td>${r.metrics?.completion_tokens??'—'}</td><td class="summary">${esc(r.explanation||r.response||'No response')}</td></tr>`).join(''):'<tr><td colspan="7" class="inspect">No matching results.</td></tr>';document.querySelectorAll('#results tr[data-i]').forEach((tr,i)=>tr.onclick=()=>{selected=data[i];renderRows();renderInspector()})}
function renderInspector(){let r=selected;if(!r){$('#inspector').innerHTML='<div class="inspect"><div class="ilabel">No selection</div><div class="isub">Select a case row to inspect its response and metrics.</div></div>';return}$('#inspector').innerHTML=`<div class="inspect"><div class="ilabel">Case</div><div class="ititle">${esc(r.case)}</div><div class="isub">${esc(r.model)}</div><div class="kv"><span>status</span><b>${esc(r.status||'completed')}</b><span>pass</span><b class="${r.pass?'pass':'fail'}">${r.pass?'yes':'no'}</b><span>latency</span><b>${r.metrics?.elapsed_ms??'—'} ms</b><span>throughput</span><b>${r.metrics?.tok_per_sec??'—'} tok/s</b></div></div><div class="inspect"><div class="ilabel">Response / explanation</div><div class="response">${esc((r.explanation?r.explanation+'\n\n':'')+(r.response||''))}</div></div>`}
function renderSummary(){let entries=Object.entries(summaries);if(!entries.length)return;let best=entries.slice().sort((a,b)=>(b[1].pass_rate||0)-(a[1].pass_rate||0))[0],base=entries.find(x=>x[0]==='base')||entries[0],rate=best[1].pass_rate||0;$('#best').textContent=best[0];$('#bestRate').textContent=(rate*100).toFixed(1)+'% pass';$('#delta').textContent=(rate-(base[1].pass_rate||0)>=0?'+':'')+((rate-(base[1].pass_rate||0))*100).toFixed(1)+' pp';$('#total').textContent=rows.length;let speeds=entries.map(x=>Number(x[1].tok_per_sec)).filter(Number.isFinite);$('#speed').textContent=speeds.length?(speeds.reduce((a,b)=>a+b,0)/speeds.length).toFixed(1):'—';$('#chartText').innerHTML=entries.map(([id,s])=>`<div class="kv"><span>${esc(id)}</span><b>${((s.pass_rate||0)*100).toFixed(1)}% · ${s.tok_per_sec??'—'} tok/s</b></div>`).join('');let names=entries.map(x=>x[0]),w=480,h=170,p=30,pts=entries.map(([_,s],i)=>`${p+i*(w-p*1.5)/Math.max(1,entries.length-1)},${h-35-(s.pass_rate||0)*100}`).join(' ');$('#line').innerHTML=`<polyline points="${pts}" fill="none" stroke="var(--green)" stroke-width="2"/>${entries.map(([id,s],i)=>`<circle cx="${p+i*(w-p*1.5)/Math.max(1,entries.length-1)}" cy="${h-35-(s.pass_rate||0)*100}" r="4" fill="var(--green)"/><text x="${p+i*(w-p*1.5)/Math.max(1,entries.length-1)}" y="${h-10}" text-anchor="middle" fill="var(--faint)" font-size="9">${esc(id)}</text>`).join('')}`}
function finish(x){let r=rows.find(y=>y.model===x.model&&y.case===x.case);if(!r){r={model:x.model,case:x.case};rows.push(r)}Object.assign(r,{status:'completed',pass:!!x.score?.pass,explanation:x.score?.explanation||'',response:x.response||'',metrics:x.metrics||{}});renderRows();}
async function load(id){let d=await (await fetch('/api/runs/'+encodeURIComponent(id))).json();rows=[];summaries=d.summary||{};for(const m of d.models||[])for(const r of m.responses||[])finish({model:m.id,case:r.case_id,response:r.text||r.error,score:r.score||{pass:false,explanation:r.error},metrics:r});$('#runId').textContent=id;$('#statusRun').textContent=id;renderSummary();renderLadder()}
function renderLadder(){let ids=Object.entries(summaries);$('#candidateCount').textContent=ids.length;$('#ladder').innerHTML=ids.map(([id,s])=>`<div class="candidate ${id==='base'?'base':''}" onclick="document.querySelector('#filter').value='${esc(id)}';renderRows()"><i class="state"></i><div><div class="name">${esc(id)} ${id==='base'?'<span class="badge">BASE</span>':''}</div><div class="sub">evaluation candidate</div></div><div class="rate">${((s.pass_rate||0)*100).toFixed(1)}%</div></div>`).join('')||'<div class="inspect">No candidates in selected run.</div>'}
async function refresh(){let d=await (await fetch('/api/runs')).json();$('#historyCount').textContent=d.runs?.length||0;let latest=d.runs?.[0];if(latest)await load(latest.run_id);let m=await (await fetch('/api/models')).json();$('#models').innerHTML=(m.models||[]).map(x=>`<option value="${esc(x.id)}" selected>${esc(x.label||x.id)}</option>`).join('');$('#caseCount').textContent=(m.models||[]).length+' candidates'}
async function run(){let selected=[...$('#models').selectedOptions].map(x=>x.value);if(!selected.length)return;rows=[];summaries={};renderRows();setStatus('running',true);$('#run').disabled=true;try{let d=await (await fetch('/api/runs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({models:selected})})).json();$('#runId').textContent=d.run_id;eventSource=new EventSource(d.events_url);eventSource.onmessage=e=>{let x=JSON.parse(e.data);if(x.type==='prompt'){let r=rows.find(y=>y.model===x.model&&y.case===x.case)||{model:x.model,case:x.case,status:'running',response:''};if(!rows.includes(r))rows.push(r);r.response='PROMPT: '+x.prompt;renderRows()}else if(x.type==='delta'){let r=rows.find(y=>y.model===x.model&&y.case===x.case);if(r)r.response+=(x.text||'');renderRows()}else if(x.type==='finished')finish(x);else if(x.type==='case_error'){rows.push({model:x.model,case:x.case,status:'error',response:x.error,pass:false});renderRows()}else if(x.type==='run_finished'){eventSource.close();setStatus('finished');load(d.run_id)}}}catch(e){setStatus('error');console.error(e)}finally{$('#run').disabled=false}}
$('#run').onclick=run;$('#filter').oninput=renderRows;document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');active=t.dataset.filter;renderRows()});setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString('en-US',{hour12:false})+' UTC',1000);refresh().catch(()=>setStatus('offline'));
</script>"""
s = re.sub(r"<script>[\s\S]*?</script>", new_script, s, count=1)

HTML.write_text(s, encoding="utf-8")
print("repaired OK")
